rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'Keep the privacy journal. Follow the erasure recovery guide.';
END
$$;

ALTER TABLE privacy_journal
    DROP CONSTRAINT ck_privacy_journal_refs,
    DROP CONSTRAINT ck_privacy_journal_kind;

changeSet.sql:
ALTER TABLE privacy_journal_backup_horizon
    ADD CONSTRAINT ck_privacy_journal_backup_horizon_singleton CHECK (id = 1),
    ADD CONSTRAINT ck_privacy_journal_backup_horizon_time CHECK (oldest_backup_at <= observed_at);

CREATE FUNCTION privacy_journal_backup_horizon_write_fence() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtext('hephaestus'), hashtext('privacy-journal-backup-horizon'));
    RETURN NULL;
END
$$;
CREATE TRIGGER trg_privacy_journal_backup_horizon_write
    BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON privacy_journal_backup_horizon
    FOR EACH STATEMENT EXECUTE FUNCTION privacy_journal_backup_horizon_write_fence();

DO $$
BEGIN
    IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'hephaestus_app') THEN
        REVOKE INSERT, UPDATE, DELETE ON privacy_journal_backup_horizon FROM hephaestus_app;
    END IF;
    IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'hephaestus_backup_reporter') THEN
        GRANT SELECT, INSERT, UPDATE (observed_at, oldest_backup_at)
            ON privacy_journal_backup_horizon TO hephaestus_backup_reporter;
    END IF;
END
$$;

rollback.sql:
DO $$
BEGIN
    IF EXISTS (SELECT FROM privacy_journal) THEN
        RAISE EXCEPTION 'Keep the populated privacy journal. Follow the erasure recovery guide.';
    END IF;
END
$$;
